 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    # Find straight contiguous rails of color 5, then continue the adjacent
    # colored motif across the rail's axis.
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and g[r][c] == 5:
                c += 1
            b = c - 1
            if b > a:
                seen.add(('H', r, a, b))
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and g[r][c] == 5:
                r += 1
            b = r - 1
            if b > a:
                seen.add(('V', c, a, b))

    for orient, fixed, a, b in seen:
        if orient == 'H':
            # A vertical color pattern attached beyond either end of the rail.
            pattern = None
            for anchor in (a, b):
                for dr in (1, -1):
                    rr = fixed + dr
                    vals = []
                    while 0 <= rr < h and g[rr][anchor] not in (0, 5):
                        vals.append(g[rr][anchor])
                        rr += dr
                    if len(vals) >= 2:
                        pattern = vals if dr == 1 else vals[::-1]
                        start = fixed + dr if dr == 1 else fixed - len(vals)
                        break
                if pattern is not None:
                    break
            if pattern:
                # Pattern is repeated as a column alongside the rail.
                for cc in range(a, b + 1):
                    for i, color in enumerate(pattern):
                        rr = start + i
                        if 0 <= rr < h and g[rr][cc] == 0:
                            g[rr][cc] = color
        else:
            # Find a rectangular motif beside the rail at its terminal end.
            # The motif's row block touches the rail's lower endpoint.
            motif = None
            for dc in (1, -1):
                side = fixed + dc
                if not 0 <= side < w:
                    continue
                # collect contiguous colored rows at the endpoint on this side
                end = b
                if g[end][side] in (0, 5):
                    continue
                lo = end
                while lo > a and g[lo - 1][side] not in (0, 5):
                    lo -= 1
                hi = end
                while hi + 1 < h and g[hi + 1][side] not in (0, 5):
                    hi += 1
                rows = list(range(lo, hi + 1))
                # Extend contiguous colored motif width away from the rail.
                cols = []
                cc = side
                while 0 <= cc < w and all(g[rr][cc] not in (0, 5) for rr in rows):
                    cols.append(cc)
                    cc += dc
                if len(rows) >= 1 and cols:
                    motif = [[g[rr][cc] for cc in cols] for rr in rows]
                    break
            if motif:
                mh, mw = len(motif), len(motif[0])
                left = min(cols) if dc > 0 else max(cols)
                # Repeat the row motif along the rail, anchored to its original rows.
                for rr in range(a, b + 1):
                    src = (rr - lo) % mh
                    for j in range(mw):
                        cc = left + j if dc > 0 else left - j
                        if 0 <= cc < w and g[rr][cc] == 0:
                            g[rr][cc] = motif[src][j]
    return g
